(function(){var B64="";var url;function getUrl(){if(url)return url;var bin=atob(B64),a=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);url=URL.createObjectURL(new Blob([a],{type:"application/pdf"}));return url;}
document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest('a[href*="Sofia-Mattson-CV"]');if(!a)return;e.preventDefault();var l=document.createElement("a");l.href=getUrl();l.download="Sofia-Mattson-CV.pdf";document.body.appendChild(l);l.click();l.remove();},true);})();